from typing import List

def combinationSum4(nums: List[int], target: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def dp(rem):
        if rem == 0:
            return 1
        if rem < 0:
            return 0
        count = 0
        for num in nums:
            count += dp(rem - num)
        return count

    return dp(target)

# Test cases
