def reconstructMatrix(upper: int, lower: int, colsum: List[int]) -> List[List[int]]:
    n = len(colsum)
    if upper + lower != sum(colsum):
        return []

    matrix = [[0] * n for _ in range(2)]

    # Place 1s where colsum is 2
    for i in range(n):
        if colsum[i] == 2:
            if upper > 0 and lower > 0:
                matrix[0][i] = 1
                matrix[1][i] = 1
                upper -= 1
                lower -= 1
            else:
                return []

    # Place remaining 1s in the upper row first, then in the lower row
    for i in range(n):
        if colsum[i] == 1:
            if upper > 0:
                matrix[0][i] = 1
                upper -= 1
            elif lower > 0:
                matrix[1][i] = 1
                lower -= 1
            else:
                return []

    # Check if all 1s are placed correctly
    if upper != 0 or lower != 0:
        return []

    return matrix

