        int n = grid[0].size();
        queue<pair<pair<int, int>, int>> que;
        vector<vector<unsigned long long>> mapKey(m, vector<unsigned long long>(n, 0));
        int target = 0;

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if ('a' <= grid[i][j] && grid[i][j] <= 'f') {
                    target |= 1 << (grid[i][j] - 'a');
                    continue;
                }

                if (grid[i][j] == '@') {
                    que.emplace(pair<int, int>(i, j), 0);
                    mapKey[i][j] = 1;
                }
            }
        }

        int step = 0;
        while (!que.empty()) {
            int size = que.size();
            for (int s = 0; s < size; s++) {
                int i = que.front().first.first;
                int j = que.front().first.second;
                int keys = que.front().second;
                que.pop();

                if (keys == target) return step;

                for (int d = 0; d < 4; d++) {
                    int ni = i + dir[d][0];
                    int nj = j + dir[d][1];

                    if (ni < 0 || ni >= m || nj < 0 || nj >= n) continue;
                    if (grid[ni][nj] == '#') continue;

                    char c = grid[ni][nj];
                    if ('A' <= c && c <= 'F') {
                        int lock = c - 'A';
                        if ((keys & (1 << lock)) == 0) continue; // missing key
