                    if (mapKey[ni][nj] & (1ULL << newKeys)) continue; // already visited with same key set
                    mapKey[ni][nj] |= (1ULL << newKeys);
                    que.emplace(pair<int, int>(ni, nj), newKeys);
                }
            }
            step++;
        }

        return -1;
    }
};
