from typing import List

class TrieNode:
    def __init__(self):
        self.children = [None, None]

def insert(root: TrieNode, num: int) -> None:
    node = root
    for i in range(40, -1, -1):  # Assuming max value is less than 2^40
        bit = (num >> i) & 1
        if not node.children[bit]:
            node.children[bit] = TrieNode()
        node = node.children[bit]

def maxXOR(root: TrieNode, num: int) -> int:
    node = root
    xor_sum = 0
    for i in range(40, -1, -1):
        bit = (num >> i) & 1
        if node.children[1 - bit]:
            xor_sum |= (1 << i)
            node = node.children[1 - bit]
        elif node.children[bit]:
            node = node.children[bit]
        else:
            break
    return xor_sum

def dfs(node: int, parent: int, graph: List[List[int]], values: List[int], subtree_sums: List[int]) -> int:
    sum_val = values[node]
    for neighbor in graph[node]:
        if neighbor != parent:
            sum_val += dfs(neighbor, node, graph, values, subtree_sums)
    subtree_sums[node] = sum_val
    return sum_val

def maxScore(n: int, edges: List[List[int]], values: List[int]) -> int:
    if n < 2:
        return 0

    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    subtree_sums = [0] * n
    dfs(0, -1, graph, values, subtree_sums)

    root = TrieNode()
    max_xor = 0

    # Insert all subtree sums into the trie except the last one processed
    for i in range(n):
        if i != n-1:
            insert(root, subtree_sums[i])

    # For each subtree sum, calculate the maximum XOR with previously inserted sums
    for i in range(n):
        max_xor = max(max_xor, maxXOR(root, subtree_sums[i]))
        if i < n-1:  # Insert current subtree sum into trie after calculation
            insert(root, subtree_sums[i])

    return max_xor

